-- 1. Create the SYSTEM_PERMISSIONS table
CREATE TABLE "CONTROL_UNIT"."SYSTEM_PERMISSIONS" (
    "ID" NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "USER_ID" NUMBER NOT NULL,          -- References mog_users.users_list.id
    "SYSTEM_KEY" VARCHAR2(50) NOT NULL, -- System or action permission key
    "GRANTED_BY" VARCHAR2(100),         -- Email or Name of admin who granted this
    "GRANTED_AT" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT "UK_USER_SYSTEM" UNIQUE ("USER_ID", "SYSTEM_KEY")
);

-- 2. Add Comments for Documentation
COMMENT ON TABLE "CONTROL_UNIT"."SYSTEM_PERMISSIONS" IS 'Centralized permissions mapping users to monolith sub-systems';
COMMENT ON COLUMN "CONTROL_UNIT"."SYSTEM_PERMISSIONS"."USER_ID" IS 'Foreign key to mog_users.users_list.id (SSO users)';
COMMENT ON COLUMN "CONTROL_UNIT"."SYSTEM_PERMISSIONS"."SYSTEM_KEY" IS 'System or action permission key';

